export const federationSource={url:'https://www.voleibolib.net/clasificaciones?id=8244&desp=30011',endpoint:'https://www.voleibolib.net/JSON/get_clasificacion.asp?id=8244',competition:'Cadete femenina · 1ª División · Mallorca',teamId:'b0000000-0000-4000-8000-000000000003',seasonId:'b0000000-0000-4000-8000-000000000002',season:'2026/27',cacheKey:'cvb:official-standings:8244:v1'};
export function sourceFor(identity){const team=identity?.teams?.[0];return team?.id===federationSource.teamId&&team?.season_id===federationSource.seasonId?federationSource:null;}
function plain(value){return value.replace(/<[^>]*>/g,' ').replace(/&(#x[\da-f]+|#\d+|amp|lt|gt|quot|apos|nbsp);/gi,(all,key)=>{if(key[0]==='#'){const n=key[1].toLowerCase()==='x'?parseInt(key.slice(2),16):Number(key.slice(1));return n>0&&n<=0x10ffff?String.fromCodePoint(n):'';}return {amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",nbsp:' '}[key.toLowerCase()]||all;}).replace(/\s+/g,' ').trim();}
export function parseFederationStandings(html){
 if(typeof html!=='string'||html.length>500000)throw Error('Formato de clasificación no válido.');
 const clean=html.replace(/<!--[\s\S]*?-->/g,'').replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi,'');
 for(const table of clean.matchAll(/<table\b[^>]*>([\s\S]*?)<\/table>/gi)){
 const trs=[...table[1].matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)].map(m=>m[1]),headers=[...(trs[0]||'').matchAll(/<th\b[^>]*>([\s\S]*?)<\/th>/gi)].map(m=>plain(m[1]).toUpperCase());
 const required=['EQUIPO','PJ','PG','PP','JF','JC','PT'];if(!required.every(k=>headers.includes(k)))continue;
 const rows=trs.slice(1).map(tr=>{const cells=[...tr.matchAll(/<td\b[^>]*>([\s\S]*?)<\/td>/gi)].map(m=>plain(m[1]));if(cells.length!==headers.length)throw Error('La tabla federativa ha cambiado de formato.');
 const number=(column,signed=false)=>{const text=cells[headers.indexOf(column)];if(!(signed?/^-?\d+$/:/^\d+$/).test(text))throw Error('Hay datos federativos incompletos.');const n=Number(text);if(!Number.isSafeInteger(n)||Math.abs(n)>1000000)throw Error('Valor federativo no válido.');return n;};
 if(!/^\d+\.?$/.test(cells[0]))throw Error('Posición federativa no válida.');const name=cells[headers.indexOf('EQUIPO')];if(!name||name.length>200)throw Error('Equipo federativo no válido.');
 return {rank:Number(cells[0].replace('.','')),name,points:number('PT',true),pj:number('PJ'),pg:number('PG'),pp:number('PP'),sf:number('JF'),sc:number('JC'),is_own:/CV\s*BUNYOLA/i.test(name)};});
 if(rows.length<2||rows.length>100||rows.filter(r=>r.is_own).length!==1||new Set(rows.map(r=>r.name.toUpperCase())).size!==rows.length||rows.some((r,i)=>r.rank!==i+1||r.pg+r.pp>r.pj))throw Error('No se ha podido validar la clasificación completa.');return rows;
 }
 throw Error('No se encontró la tabla de clasificación federativa.');
}
export async function fetchFederationStandings(fetcher=fetch,signal){const response=await fetcher(federationSource.endpoint,{signal,credentials:'omit',cache:'no-store'});if(!response.ok)throw Error(`La federación no responde (${response.status}).`);const rows=parseFederationStandings(await response.text());return {rows,checkedAt:new Date().toISOString()};}
export function readStandingsCache(storage){try{const data=JSON.parse(storage.getItem(federationSource.cacheKey));if(!data||!Array.isArray(data.rows)||!Number.isFinite(Date.parse(data.checkedAt)))return null;const rows=data.rows;if(rows.length<2||rows.length>100||rows.filter(r=>r.is_own===true).length!==1||rows.some((r,i)=>r.rank!==i+1||typeof r.name!=='string'||['points','pj','pg','pp','sf','sc'].some(k=>!Number.isSafeInteger(r[k]))))return null;return data;}catch{return null;}}
